const body = $input.first().json.body || {};

// Honeypot — a real visitor never fills this (hidden via CSS on the
// public form); a bot filling every field will. Silently pretend
// success without touching the database.
if ((body.website_hp || '').toString().trim()) {
  return [{ json: { spam: true } }];
}

const firstName = (body.first_name || '').toString().trim();
const lastName = (body.last_name || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const phone = (body.phone || '').toString().trim();
const jobTitle = (body.job_title || '').toString().trim();
const leadSource = (body.lead_source || 'Website Form').toString().trim();

if (!firstName) throw new Error('"first_name" is required.');
if (!email && !phone) throw new Error('Either "email" or "phone" is required.');
if (email && !email.includes('@')) throw new Error('"email" is not valid.');

return [{
  json: {
    spam: false, source: 'public',
    first_name: firstName, last_name: lastName, email, secondary_email: '', phone, secondary_phone: '',
    job_title: jobTitle, account_id: null, linkedin_url: '', city: '', state: '', zip_code: '', country: '',
    lead_status: 'New', lead_source: leadSource, timezone: '',
    do_not_contact: false, dnc_email: false, dnc_call: false, dnc_sms: false,
    ownerId: null, createdBy: null,
  },
}];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');
return [{ json: { requesterId: parseInt(match[1], 10) } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const body = $('Webhook: add-contact').first().json.body || {};

const firstName = (body.first_name || '').toString().trim();
if (!firstName) throw new Error('"first_name" is required.');
const rawOwnerId = (body.owner_id === undefined || body.owner_id === null || body.owner_id === '') ? null : parseInt(body.owner_id, 10);
// Only an admin may hand a brand-new contact to someone else at creation time.
const ownerId = (requester.role === 'admin' && Number.isInteger(rawOwnerId)) ? rawOwnerId : requester.id;

return [{
  json: {
    spam: false, source: 'manual', requesterId: requester.id,
    first_name: firstName, last_name: (body.last_name || '').toString().trim(),
    email: (body.email || '').toString().trim().toLowerCase(), secondary_email: (body.secondary_email || '').toString().trim(),
    phone: (body.phone || '').toString().trim(), secondary_phone: (body.secondary_phone || '').toString().trim(),
    job_title: (body.job_title || '').toString().trim(), account_id: body.account_id ? parseInt(body.account_id, 10) : null,
    linkedin_url: (body.linkedin_url || '').toString().trim(), city: (body.city || '').toString().trim(),
    state: (body.state || '').toString().trim(), zip_code: (body.zip_code || '').toString().trim(), country: (body.country || '').toString().trim(),
    lead_status: (body.lead_status || 'New').toString().trim(), lead_source: (body.lead_source || '').toString().trim(),
    timezone: (body.timezone || '').toString().trim(),
    do_not_contact: body.do_not_contact === true || body.do_not_contact === 'true',
    dnc_email: body.dnc_email === true || body.dnc_email === 'true',
    dnc_call: body.dnc_call === true || body.dnc_call === 'true',
    dnc_sms: body.dnc_sms === true || body.dnc_sms === 'true',
    ownerId, createdBy: requester.id,
  },
}];

// A resubmission / repeat manual-add of the same email updates the
// existing lead instead of creating a duplicate or rejecting outright —
// consistent dedup-by-email across both entry points now.
const payload = $('Normalize Payload').item.json;
const existing = $input.first().json;
return [{ json: { ...payload, existingContactId: existing?.id || null } }];

function toTitleCase(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function fill(t, row) { return (t || '').replace(/{{\s*first_name\s*}}/gi, toTitleCase(row.first_name) || 'there').replace(/{{\s*email\s*}}/gi, row.email || '').replace(/{{[^{}]*}}/g, ''); }
const tmpl = $input.item.json;
const row = $('Postgres: Upsert Contact').item.json;
return [{ json: { to: row.email, subject: fill(tmpl.subject, row), htmlBody: fill(tmpl.body, row).replace(/\n/g, '<br>') } }];
